describe('the 22 recorded figures', () => {
  it('draws thirteen of them exactly as the site does', () => {
    expect(VECTORS.svg).toHaveLength(22);
    let same = 0;
    for (const row of VECTORS.svg) {
      if (CORRECTED_FIGURES[row.name] === undefined) same++;
    }
    expect(same).toBe(13);
  });

  for (const row of VECTORS.svg) {
    it(`${row.name}: ${row.expr}`, () => {
      const source = `x: ${row.xMin}..${row.xMax}\ny: ${row.yMin}..${row.yMax}\n${row.expr}`;
      const got = facts(plotSVG(source));
      const fix = CORRECTED_FIGURES[row.name] ?? {};

      // The spacing is `nice_step`, ported verbatim: never corrected.
      expect(bits(niceStep(row.xMax - row.xMin))).toBe(bits(row.xStep));
      expect(bits(niceStep(row.yMax - row.yMin))).toBe(bits(row.yStep));

      expect(got.lines, 'grid + axis lines').toBe(fix.lines ?? row.lineCount);
      expect(got.texts, 'tick labels').toBe(fix.texts ?? row.textCount);
      expect(got.polylines, 'unbroken runs').toBe(fix.polylines ?? row.polylineCount);
      expect(got.first, 'first plotted point').toBe(
        fix.first !== undefined ? fix.first : row.firstPoint,
      );
      expect(got.last, 'last plotted point').toBe(fix.last !== undefined ? fix.last : row.lastPoint);
      expect(got.xLabels, 'x tick labels').toEqual(fix.xLabels ?? row.xTickLabels);
      expect(got.yLabels, 'y tick labels').toEqual(fix.yLabels ?? row.yTickLabels);
    });
  }

  it('breaks a curve where it leaves the window, and nowhere else', () => {
    // tan(x) over [-10, 10] is seven branches; 1/x over [-5, 5] is two; a
    // single plottable sample is still a polyline of one point.
    expect(figure('x: -10..10\ny: -2..2\ntan(x)').polylines).toBe(7);
    expect(figure('x: -5..5\ny: -5..5\n1/x').polylines).toBe(2);
    expect(figure('x: -10..10\ny: -0.005..0.005\nx').first).toBe('300.00,200.00');
  });

  it('samples with the formula the site uses, not the cheaper one', () => {
    // `xMin + (i / samples) * span`, never `xMin + i * dx`: the two differ in
    // the last bits for 221 of the 1001 default samples, and the difference
    // reaches the output.
    const chart = figure('x: -6.3..0.7999999999999998\ny: -3.3..3.1\nx');
    expect(chart.first).toBe('259.96,359.83');
    expect(chart.last).toBe('560.00,155.00');
  });
});

// MARK: - §6 The fence

describe('the fence', () => {
  it('reads directives in any order, and ignores blanks and comments', () => {
    const spec = parsePlot(
      ['# a comment', '', 'sin(x)', 'title: A title', 'x: -1..1', 'y: -2..2', ''].join('\n'),
    );
    expect(spec.title).toBe('A title');
    expect(spec.xMin).toBe(-1);
    expect(spec.xMax).toBe(1);
    expect(spec.yMin).toBe(-2);
    expect(spec.series).toHaveLength(1);
  });

  it('treats an unknown key: line as a labelled series, not as an error', () => {
    // `f: x` still plots. This is why the directive scan checks the key
    // against the known list before it claims the line, and why the series
    // parser then reads the key as a label.
    const spec = parsePlot('f: x');
    expect(spec.series).toHaveLength(1);
    expect(spec.series[0].label).toBe('f');
    expect(spec.series[0].source).toBe('x');
    expect(plotSVG('f: sin(x)')).toContain('<polyline');
  });

  it('defaults to -10..10, auto, 600 × 400, 1000 samples', () => {
    const spec = parsePlot('sin(x)');
    expect([spec.xMin, spec.xMax]).toEqual([-10, 10]);
    expect(spec.yMin).toBeNull();
    expect([spec.width, spec.height, spec.samples]).toEqual([600, 400, 1000]);
    expect(spec.legend).toBe('auto');
    expect(spec.grid).toBe(true);
    expect(spec.axes).toBe(true);
  });

  it('clamps width, height and samples', () => {
    expect(parsePlot('width: 10\nheight: 10\nsamples: 1\nx').width).toBe(160);
    expect(parsePlot('width: 10\nheight: 10\nsamples: 1\nx').height).toBe(120);
    expect(parsePlot('width: 10\nheight: 10\nsamples: 1\nx').samples).toBe(50);
    expect(parsePlot('width: 9000\nheight: 9000\nsamples: 90000\nx').width).toBe(2000);
    expect(parsePlot('width: 9000\nheight: 9000\nsamples: 90000\nx').height).toBe(2000);
    expect(parsePlot('width: 9000\nheight: 9000\nsamples: 90000\nx').samples).toBe(5000);
  });

  it('takes a constant expression at either end of a range', () => {
    const spec = parsePlot('x: -pi..2*pi\nsin(x)');
    expect(spec.xMin).toBe(-Math.PI);
    expect(spec.xMax).toBe(2 * Math.PI);
  });

  it('rejects a range that does not increase', () => {
    expect(() => parsePlot('x: 1..1\nx')).toThrow('x range must be increasing');
    expect(() => parsePlot('y: 5..-5\nx')).toThrow('y range must be increasing');
    expect(() => parsePlot('x: nonsense\nx')).toThrow(PlotError);
  });

  it('splits a label off the first top-level bare =', () => {
    expect(parsePlot('envelope = exp(-abs(x)/5)').series[0].label).toBe('envelope');
    expect(parsePlot('envelope = exp(-abs(x)/5)').series[0].source).toBe('exp(-abs(x)/5)');
    // The FIRST one, so what follows still has to be an expression: there is
    // no assignment in the language for a second `=` to be part of.
    expect(() => parsePlot('a = b = x')).toThrow(PlotError);
    // …and never off a comparison operator.
    for (const source of ['x == 1', 'x <= 1', 'x >= 1', 'x != 1']) {
      expect(parsePlot(source).series[0].label, source).toBeNull();
    }
  });

  it('reads a points series and a parametric series', () => {
    const points = parsePlot('measured = points: 0,0 1,2 2,1').series[0];
    expect(points.kind).toBe('points');
    expect(points.label).toBe('measured');
    expect(points.points).toEqual([
      { x: 0, y: 0 },
      { x: 1, y: 2 },
      { x: 2, y: 1 },
    ]);

    const parametric = parsePlot('circle = (cos(t), sin(t)) for t in 0..2*pi').series[0];
    expect(parametric.kind).toBe('parametric');
    expect(parametric.parameter).toBe('t');
    expect(parametric.tMin).toBe(0);
    expect(parametric.tMax).toBe(2 * Math.PI);
    // The parametric variable is the only free name inside it: `x` is not.
    expect(() => parsePlot('(x, sin(t)) for t in 0..1')).toThrow("unknown name 'x'");
  });

  it('does not mistake a parenthesised expression for a parametric one', () => {
    expect(parsePlot('(x+1)*2').series[0].kind).toBe('function');
    // A pair with no `for` is not a parametric series, so it is read as an
    // expression — and a tuple is not one of those.
    expect(() => parsePlot('(x, x)')).toThrow(PlotError);
  });

  it('fits y: auto to the finite samples, with 5 % of padding', () => {
    // sin over a whole period reaches ±1 (to the last sample), so the window
    // is 1.05 either way.
    const svg = plotSVG('x: -10..10\nsin(x)');
    expect(svg).toContain('>1</text>'); // a tick at 1 is inside the window
    // A series with nothing finite in it falls back to -1..1.
    expect(plotSVG('x: -10..10\nsqrt(-1)+x*0')).toContain('>1</text>');
    // A flat series has no span to take 5 % of: it is padded by 5 % of itself.
    const flat = parsePlot('x: -1..1\n3');
    expect(flat.series).toHaveLength(1);
    expect(plotSVG('x: -1..1\n3')).toContain('<polyline');
  });

  it('shows the legend when there are two series, or one that is labelled', () => {
    expect(plotSVG('x: -1..1\nsin(x)')).not.toContain('font-size="11" font-family="sans-serif"');
    expect(plotSVG('x: -1..1\nsin(x)\ncos(x)')).toContain('font-size="11" font-family="sans-serif"');
    expect(plotSVG('x: -1..1\nwave = sin(x)')).toContain('>wave</text>');
    expect(plotSVG('x: -1..1\nlegend: off\nsin(x)\ncos(x)')).not.toContain(
      'font-size="11" font-family="sans-serif"',
    );
    // An unlabelled series' legend text is its own source.
    expect(plotSVG('x: -1..1\nlegend: on\nsin(x)')).toContain('>sin(x)</text>');
  });

  it('turns the grid and the axes off', () => {
    const bare = plotSVG('x: -1..1\ngrid: off\naxes: off\nx');
    expect(bare).not.toContain('<line');
    expect(bare).not.toContain('<text x=');
    expect(bare).not.toContain('<rect');
    expect(bare).toContain('<polyline');
    expect(() => parsePlot('grid: sometimes\nx')).toThrow("grid must be 'on' or 'off'");
  });

  it('gives each series the next colour, purple first', () => {
    const svg = plotSVG('x: -1..1\nx\nx+0.1\nx+0.2');
    expect(svg).toContain('stroke="#673AB7"');
    expect(svg).toContain('stroke="#E5390F"');
    expect(svg).toContain('stroke="#0F9D58"');
  });
});

// MARK: - §7 The container, and what must never be in it

describe('the emitted markup', () => {
  const svg = plotSVG('x: -10..10\ntitle: T\nsin(x)');

  it('is a div.plot around one svg with a viewBox', () => {
    const block = renderPlot('x: -10..10\nsin(x)');
    expect(block.startsWith('<div class="plot"><svg ')).toBe(true);
    expect(block.endsWith('</svg></div>')).toBe(true);
    // Without a viewBox, `max-width: 100%; height: auto` shrinks the box and
    // clips the drawing instead of scaling it.
    expect(block).toContain('viewBox="0 0 600 400"');
    expect(block).toContain('width="600" height="400" role="img"');
  });

  it('carries no id at all', () => {
    // SPEC §1.5: a duplicated id is how one figure ends up wearing another's
    // clip path once a document holds two plots and morphdom patches the
    // preview. An `<svg role="img">` is named by its own `<title>`, with no
    // `aria-labelledby` to point at, so there is nothing to number.
    const two = renderPlot('sin(x)') + renderPlot('cos(x)');
    expect(two).not.toContain(' id=');
    expect(two).not.toContain('aria-labelledby');
    expect(svg).toContain('<title>T</title>');
    expect(plotSVG('sin(x)')).toContain('<title>Plot of sin(x)</title>');
  });

  it('paints with currentColor and bakes only the series colours', () => {
    // `renderBlock` is theme-blind in all four repos, so one SVG has to be
    // right in a light preview, a dark preview, print, an exported page and a
    // saved file. A baked grey is a light-mode assumption.
    expect(svg).toContain('stroke="currentColor"');
    expect(svg).toContain('fill="currentColor"');
    for (const grey of ['#e0e0e0', '#999', '#666', '#ccc']) expect(svg).not.toContain(grey);
    expect(svg).not.toContain('background:white');
    expect(svg).toContain('stroke="#673AB7"');
  });

  it('embeds no style, script, foreignObject or font', () => {
    // An SVG `<style>` inside an HTML document is document-scoped and leaks.
    for (const forbidden of ['<style', '<script', '<foreignObject', '@font-face', '<image']) {
      expect(svg, forbidden).not.toContain(forbidden);
    }
  });

  it('XML-escapes every author string, with the five XML entities and no other', () => {
    // The EPUB body is XHTML, which is XML: one raw `&` makes the whole
    // content document unparseable and the book unopenable. And a named
    // entity like `&nbsp;` is undefined in XML, so escaping may only ever
    // produce the five.
    const hostile = plotSVG(
      ['title: A & B <c> "d"', 'xlabel: <x>', 'ylabel: &y;', 'p & q = x'].join('\n'),
    );
    expect(hostile).toContain('<title>A &amp; B &lt;c&gt; &quot;d&quot;</title>');
    expect(hostile).toContain('>&lt;x&gt;</text>');
    expect(hostile).toContain('>&amp;y;</text>');
    expect(hostile).toContain('>p &amp; q</text>');
    expect(hostile).not.toContain('&nbsp;');
    for (const entity of [...hostile.matchAll(/&[a-z]+;/g)].map((m) => m[0])) {
      expect(['&amp;', '&lt;', '&gt;', '&quot;', '&apos;']).toContain(entity);
    }
  });

  it('emits the container even for an empty block and a broken one', () => {
    // If it is ever omitted the SVG-export ordinals desynchronise and every
    // later diagram exports the wrong figure.
    expect(renderPlot('')).toBe('<div class="plot"></div>');
    expect(renderPlot('# only a comment')).toBe('<div class="plot"></div>');
    const broken = renderPlot('sinc(x)');
    expect(broken.startsWith('<div class="plot"><pre>')).toBe(true);
    expect(broken).toContain("plot: unknown function 'sinc'");
    expect(broken).toContain('sinc(x)'); // the source always stays visible
    expect(renderPlot('x: 1..1\nx')).toContain('plot: x range must be increasing');
  });

  it('escapes the source it falls back to', () => {
    expect(renderPlot('<b>&</b>')).toContain('&lt;b&gt;&amp;&lt;/b&gt;');
  });

  it('never returns anything but a container, whatever it is handed', () => {
    // The renderer runs inside the Markdown renderer, which has no other
    // failure mode: whatever a fence contains, the answer is a `div.plot` with
    // either a drawing or the source in it, and every coordinate in that
    // drawing is a real number. A stack overflow on 200 nested parentheses is
    // caught here too — it is a RangeError rather than a PlotError, and it
    // still comes back as the author's own text.
    const hostile = [
      '', '   ', '#', 'x: 0..0\nx', 'y: 1..0\nx', 'width: -5\nheight: abc\nx',
      'points:', 'points: 1', 'label =', '= x', '(cos(t), sin(t)) for t in 0..0',
      '(cos(t), sin(t)) for u in 0..1', 'x: 1e308..-1e308\nx', 'x: -1e308..1e308\nx',
      'x: 0.0000001..0.0000002\nx', 'axes: off\ngrid: off\nx', 'ln(x)', 'x^x',
      'sqrt(-x)', '0/0', 'x*0/0', '('.repeat(200) + 'x', 'title: ' + 'A'.repeat(500) + '\nx',
      'y: -1..1\n' + 'sin(x)\n'.repeat(12),
    ];
    for (const source of hostile) {
      const html = renderPlot(source);
      expect(html.startsWith('<div class="plot">'), source).toBe(true);
      expect(html.endsWith('</div>'), source).toBe(true);
      for (const attribute of html.matchAll(/ (?:x|y|x1|y1|x2|y2|width|height|cx|cy)="([^"]*)"/g)) {
        expect(Number.isFinite(Number(attribute[1])), `${source} → ${attribute[1]}`).toBe(true);
      }
      for (const run of html.matchAll(/points="([^"]*)"/g)) {
        for (const pair of run[1].split(' ')) {
          const [x, y] = pair.split(',');
          expect(Number.isFinite(Number(x)) && Number.isFinite(Number(y)), pair).toBe(true);
        }
      }
    }
  });

  it('survives a figure squeezed to the smallest canvas', () => {
    // Title, both axis labels and a legend on a 160 × 120 canvas would compute
    // a negative plot area without `fitMargins`.
    const tiny = plotSVG(
      ['width: 160', 'height: 120', 'title: T', 'xlabel: x', 'ylabel: y', 'legend: on', 'a = x'].join('\n'),
    );
    expect(tiny).toContain('viewBox="0 0 160 120"');
    expect(tiny).not.toContain('NaN');
    // The plot area is still a real rectangle, inside the canvas.
    const rect = /<rect x="([\d.]+)" y="([\d.]+)" width="([\d.]+)" height="([\d.]+)"/.exec(tiny);
    expect(rect).not.toBeNull();
    const [x, y, w, h] = (rect as RegExpExecArray).slice(1).map(Number);
    expect(w).toBeGreaterThanOrEqual(40);
    expect(h).toBeGreaterThanOrEqual(40);
    expect(x + w).toBeLessThanOrEqual(160);
    expect(y + h).toBeLessThanOrEqual(120);
  });
});

// MARK: - §8 The renderer, the settings and every export path

const FENCE = ['```plot', 'x: -10..10', 'sin(x)', '```'].join('\n');

describe('integration', () => {
  it('dispatches the fence to a plot container', () => {
    const { html, needs } = renderBody(FENCE, { title: 't', dark: false });
    expect(html.startsWith('<div class="plot"><svg')).toBe(true);
    // The class is exactly `plot`, which keeps all five engine probes false: a
    // plot-only document loads no engine at all, and there is no `needs` flag
    // to add.
    expect(needs).toEqual({
      math: false,
      mermaid: false,
      plantuml: false,
      graphviz: false,
      highlight: false,
    });
  });

  it('leaves the source visible when md.diagrams.plot is off', () => {
    const html = renderBody(FENCE, { title: 't', dark: false, plot: false }).html;
    expect(html).toBe('<div class="plot"><pre>x: -10..10\nsin(x)</pre></div>');
  });

  it('is styled by both stylesheets — the exported one and the preview’s', () => {
    // Two sheets, because VS Code's built-in preview is styled by
    // `media/preview/md-preview.css` and every export by `css-text.ts`. The
    // rules are *joined*, never added: `html.test.ts` pins each variant at
    // exactly 101 lines.
    const exported = renderDocument(FENCE, { title: 't', dark: false });
    expect(exported).toContain('.mermaid, .plantuml, .graphviz, .plot, .md-mathd {');
    expect(exported).toContain('.graphviz svg, .plot svg { max-width: 100%; height: auto; }');
    const preview = fs.readFileSync(
      path.join(__dirname, '..', 'media', 'preview', 'md-preview.css'),
      'utf8',
    );
    expect(preview).toContain('body .markdown-body .plot,');
    expect(preview).toContain('body .markdown-body .plot svg {');
  });

  it('offers the figure to the SVG export, and finds it in the DOM', () => {
    const document = [FENCE, '', '```dot', 'digraph {}', '```'].join('\n');
    const found = diagrams(document);
    expect(found.map((d) => d.kind)).toEqual(['plot', 'graphviz']);
    expect(typeName(found[0])).toBe('Plot');
    expect(menuTitle(found[0])).toBe('Plot: x: -10..10');
    // The walk and the DOM query must agree about what a diagram is, or every
    // later figure exports as the wrong one.
    expect(DIAGRAM_SELECTOR).toContain('div.plot');
    // A quoted plot keeps its place, because the renderer recurses into quotes.
    expect(diagrams(['> ```plot', '> sin(x)', '> ```'].join('\n')).map((d) => d.kind)).toEqual([
      'plot',
    ]);
  });

  it('saves as a standalone .svg without a fix-up', () => {
    // The root already carries `xmlns`, `width` and `height`, so the only
    // thing the writer adds is the XML prolog.
    const file = standaloneDocument(plotSVG('sin(x)'));
    expect(file.startsWith('<?xml version="1.0" encoding="UTF-8"?>\n<svg xmlns=')).toBe(true);
    expect(file).toContain('width="600" height="400"');
  });

  it('keeps the source in the LaTeX export, under a comment', () => {
    const tex = latexDocument(FENCE);
    expect(tex).toContain('% plot diagram source');
    expect(tex).toContain('\\begin{verbatim}');
    expect(tex).toContain('sin(x)');
  });

  it('passes the EPUB’s XHTML fixer untouched, and asks for properties="svg"', () => {
    // The fixers have never seen an SVG before: `xhtml` self-closes void
    // elements with an *unanchored* alternation, so `<line>` and `<polyline>`
    // are exactly the shapes to check before trusting it.
    const body = renderBody(FENCE, { title: 't', dark: false }).html;
    expect(body).toContain('<line ');
    expect(body).toContain('<polyline ');
    expect(xhtml(body)).toBe(body);

    // EPUB 3 requires the reserved property on any content document holding an
    // `<svg>`; without it EPUBCheck reports OPF-014 and the book is invalid.
    expect(
      contentOPF({
        title: 't',
        identifier: 'i',
        modified: 'm',
        units: [{ id: 'content', href: 'content.xhtml', svg: true }],
        images: [],
      }),
    ).toContain('<item id="content" href="content.xhtml" media-type="application/xhtml+xml" properties="svg"/>');
    // …and a document without one is still emitted bare.
    expect(
      contentOPF({
        title: 't',
        identifier: 'i',
        modified: 'm',
        units: [{ id: 'content', href: 'content.xhtml' }],
        images: [],
      }),
    ).toContain('<item id="content" href="content.xhtml" media-type="application/xhtml+xml"/>');
  });
});

// MARK: - §9 The figure itself, byte for byte

describe('golden figure', () => {
  // The whole SVG of one document, pinned. Not a specification and not
  // documentation: a tripwire, so that a change to a coordinate, an opacity or
  // an attribute order shows up as a diff to read rather than as nothing at
  // all. Regenerate with `npx vitest run -u` and read every hunk.
  //
  // It is also the file the three other ports are diffed against: same fence,
  // same bytes, in Swift and in Kotlin.
  it('draws the spec’s own example as recorded', async () => {
    const source = [
      'x: -10..10',
      'y: -2..2',
      'title: Damped oscillation',
      'xlabel: x',
      'ylabel: amplitude',
      'envelope = exp(-abs(x)/5)',
      'sin(x) * exp(-abs(x)/5)',
    ].join('\n');
    await expect(renderPlot(source) + '\n').toMatchFileSnapshot(
      path.join(GOLDEN, 'plot-damped-oscillation.svg'),
    );
  });
});

describe('resource limits and degenerate magnitudes', () => {
  // Each of these was found by an adversarial pass against the first cut of
  // this file, and each is a way the reference could have taught the same
  // defect to the Swift and Kotlin ports. A stack overflow is an exception
  // here and a crash there, so the guards matter more downstream than they do
  // in this repo.

  it('draws a series whose values overflow the padded range', () => {
    // `high - low` overflows for a series straddling ~1e308, which made every
    // sy() NaN and emitted points="40.00,NaN …" — a curve that vanished with
    // nothing to say why.
    const out = renderPlot('x: -10..10\nx*1e307');
    expect(out).not.toContain('NaN');
    expect(out).toContain('<polyline');
  });

  it('leaves a huge but narrow range exactly as asked', () => {
    // The guard must fire on an overflowing *width*, not on a large bound:
    // [1.69e308, 1.71e308] is only 2e306 wide and is perfectly drawable.
    const out = renderPlot('x: -1..1\ny: 1.69e308..1.71e308\n1.7e308');
    expect(out).not.toContain('NaN');
    expect(out).toContain('<polyline');
  });

  it('reports deep nesting as a plot: line, not a stack overflow', () => {
    const source = 'x: -1..1\n' + '('.repeat(5000) + 'x' + ')'.repeat(5000);
    expect(renderPlot(source)).toContain('plot: expression nested too deeply');
  });

  it('reports a long flat chain too, which the depth guard cannot see', () => {
    // `x+x+x+…` parses at constant depth through the left-associative loop and
    // then overflows the stack in the evaluator, so depth alone is not enough.
    const source = 'x: -1..1\n' + 'x' + '+x'.repeat(20000);
    expect(renderPlot(source)).toContain('plot: expression too large');
  });

  it('caps the series count, the one input with no clamp', () => {
    const source = 'x: -1..1\n' + Array.from({ length: 1000 }, (_, i) => `x*${i + 1}`).join('\n');
    expect(renderPlot(source)).toContain('plot: too many series');
  });

  it('draws the axes a directives-only block describes', () => {
    // Not an empty block: the author wrote three lines. Returning an empty
    // container would swallow them, and the family rule is never a hole.
    const out = renderPlot('x: -10..10\ntitle: My chart\nylabel: y');
    expect(out).toContain('<svg');
    expect(out).toContain('My chart');
  });

  it('still draws nothing for a genuinely empty block', () => {
    expect(renderPlot('')).toBe('<div class="plot"></div>');
  });
});

// MARK: - §10 The render cache

describe('the render cache', () => {
  // WHY IT EXISTS. The live preview rebuilds the whole HTML document on every
  // text change — the 0.35 s debounce delays the webview reload, not the
  // render — and a plot is the first rich fence whose real cost is paid at
  // that layer, synchronously, rather than in the page by an engine. Measured
  // in a release build on a Mac: 4.87 ms for one default plot, 9.52 ms for the
  // golden fence, 36 ms for an eight-series plot, 187 ms for a document with
  // four of those and 289 ms for ten `samples: 5000` plots. The per-fence
  // clamps bound a fence, not a document, and a phone is slower.
  //
  // `renderPlot` is a pure function of its source string, so memoising it on
  // exactly that string is sound by construction, and while prose is being
  // typed around them every plot in the document is a hit. Nothing in the
  // preview coordinator or the debounce is touched.

  const SOURCE = ['x: -10..10', 'y: -2..2', 'title: Damped', 'sin(x) * exp(-abs(x)/5)'].join('\n');

  it('serves a repeat render from the cache', () => {
    resetPlotCache();
    const first = renderPlot(SOURCE);
    expect(plotCacheStats()).toMatchObject({ hits: 0, misses: 1, size: 1 });

    const second = renderPlot(SOURCE);
    expect(plotCacheStats()).toMatchObject({ hits: 1, misses: 1, size: 1 });
    expect(second).toBe(first);

    // …and what the cache hands back is what a cold render produces, so the
    // memo can never be the reason two identical fences differ.
    resetPlotCache();
    expect(renderPlot(SOURCE)).toBe(first);
    expect(plotCacheStats()).toMatchObject({ hits: 0, misses: 1, size: 1 });
  });

  it('caches a failure too — the state a fence spends most of its life in', () => {
    resetPlotCache();
    const broken = 'x: -1..1\nsinc(x)';
    const out = renderPlot(broken);
    expect(out).toContain("plot: unknown function 'sinc'");
    expect(renderPlot(broken)).toBe(out);
    expect(plotCacheStats()).toMatchObject({ hits: 1, misses: 1, size: 1 });
  });

  it('holds 32 and evicts the least recently used', () => {
    resetPlotCache();
    expect(plotCacheStats().limit).toBe(32);

    const sources = Array.from({ length: 32 }, (_, i) => `x: -1..1\nx*${i + 1}`);
    for (const source of sources) {
      renderPlot(source);
      expect(plotCacheStats().size).toBeLessThanOrEqual(32);
    }
    expect(plotCacheStats()).toMatchObject({ hits: 0, misses: 32, size: 32 });

    // Touch the oldest entry so it becomes the newest. Eviction has to be by
    // *use*: otherwise the plot the author keeps re-rendering is the one thrown
    // away every 32 keystrokes.
    renderPlot(sources[0]);
    expect(plotCacheStats().hits).toBe(1);

    // The 33rd distinct fence evicts exactly one entry — and it is sources[1],
    // now the oldest by use, not sources[0], the oldest by insertion.
    renderPlot('x: -1..1\nx*33');
    expect(plotCacheStats().size).toBe(32);

    const hitsBefore = plotCacheStats().hits;
    renderPlot(sources[0]);
    expect(plotCacheStats().hits, 'sources[0] was touched and must have survived').toBe(
      hitsBefore + 1,
    );

    const missesBefore = plotCacheStats().misses;
    renderPlot(sources[1]);
    expect(plotCacheStats().misses, 'sources[1] was the least recently used and must be gone').toBe(
      missesBefore + 1,
    );
    expect(plotCacheStats().size).toBe(32);
  });

  it('never conflates two fences that differ by a character', () => {
    resetPlotCache();
    const sine = renderPlot('x: -1..1\nsin(x)');
    const cosine = renderPlot('x: -1..1\ncos(x)');
    expect(cosine).not.toBe(sine);
    expect(plotCacheStats()).toMatchObject({ hits: 0, misses: 2, size: 2 });
  });
});

